import{_ as e,c as n,o,ae as r}from"./chunks/framework.CyJo7YO6.js";const u=JSON.parse('{"title":"Whanos - Documentation for Dev","description":"","frontmatter":{},"headers":[],"relativePath":"Devs/Technincal.md","filePath":"Devs/Technincal.md"}'),a={name:"Devs/Technincal.md"};function i(s,t,d,c,h,l){return o(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="whanos-documentation-for-dev" tabindex="-1">Whanos - Documentation for Dev <a class="header-anchor" href="#whanos-documentation-for-dev" aria-label="Permalink to &quot;Whanos - Documentation for Dev&quot;">​</a></h1><h2 id="overview-of-the-projet" tabindex="-1">Overview of the projet <a class="header-anchor" href="#overview-of-the-projet" aria-label="Permalink to &quot;Overview of the projet&quot;">​</a></h2><p><strong>Whanos</strong> is an automated DevOps infrastructure that enables any developer to deploy an application into a Kubernetes cluster simply by pushing their code to a Git repository.<br> It integrates several key technologies — <strong>Docker</strong>, <strong>Jenkins</strong>, <strong>Ansible</strong>, and <strong>Kubernetes</strong> — to achieve full CI/CD automation.</p><h2 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h2><p>Whanos is built upon four main components, each representing a major DevOps principle:</p><table tabindex="0"><thead><tr><th>Technology</th><th>Role</th><th>Description</th></tr></thead><tbody><tr><td><strong>Docker</strong></td><td>Containerization</td><td>Builds standardized images for applications in different languages.</td></tr><tr><td><strong>Jenkins</strong></td><td>CI/CD Automation</td><td>Detects repository updates, triggers builds, and automates deployment pipelines.</td></tr><tr><td><strong>Ansible</strong></td><td>Configuration Management</td><td>Deploys and maintains the Whanos infrastructure on remote servers.</td></tr><tr><td><strong>Kubernetes</strong></td><td>Orchestration</td><td>Manages application deployments, scaling, and networking within the cluster.</td></tr></tbody></table>',6)])])}const g=e(a,[["render",i]]);export{u as __pageData,g as default};
